//! LuaLS annotation generation from directional JSON Schemas.

use serde_json::{Map, Value};
use std::collections::{BTreeMap, BTreeSet};

/// Repository-relative path of the generated LuaLS annotation file.
pub const ANNOTATION_PATH: &str = "clients/neovim/lua/magit-lsp/types.lua";

/// One generated LuaLS annotation file.
pub struct Annotations {
    /// Repository-relative output path.
    pub path: &'static str,
    /// Complete generated file text.
    pub text: String,
}

const HEADER: &str = concat!(
    "---@meta\n",
    "-- Generated by scripts/generate_schema.rs from docs/schema/*.json; do not edit.\n",
    "-- Run `make update-schema` to regenerate.\n",
    "--\n",
    "-- Annotation-only LuaLS mirror of the directional wire schemas. Each qualified\n",
    "-- name mirrors one schema root so input and output definitions with the same\n",
    "-- Rust name never collide.\n",
);

/// Generate the complete annotation file from the directional artifacts.
///
/// The custom method catalog and the shared capability lists are catalog data,
/// not payload schemas, so they are deliberately excluded.
pub fn protocol_annotations() -> Result<Annotations, String> {
    let mut body = String::new();
    for artifact in super::artifacts() {
        if artifact.file == "methods.json" || artifact.file == "shared-lists.json" {
            continue;
        }
        let name = root_name(&artifact.schema)?;
        if !body.is_empty() {
            body.push('\n');
        }
        body.push_str(&render_root(&artifact.schema, &name)?);
    }
    Ok(Annotations {
        path: ANNOTATION_PATH,
        text: format!("{HEADER}{body}"),
    })
}

/// Render one directional root schema as namespaced LuaLS annotations.
///
/// Local definitions become `<root>.<DefName>` declarations and the root
/// itself becomes `<root>.Root`, which keeps same-named definitions from
/// different roots apart.
pub fn render_root(schema: &Value, name: &str) -> Result<String, String> {
    validate_identifier(name)?;
    let mut root = schema.clone();
    let defs = root
        .as_object_mut()
        .ok_or_else(|| format!("{name}: schema root must be an object"))?
        .remove("$defs");
    let mut renderer = Renderer::new(name);
    renderer.declare(&root, &format!("{name}.Root"))?;
    if let Some(defs) = defs {
        let defs = defs
            .as_object()
            .ok_or_else(|| format!("{name}: `$defs` must be an object"))?;
        let sorted: BTreeMap<&String, &Value> = defs.iter().collect();
        for (def_name, definition) in sorted {
            validate_identifier(def_name)?;
            renderer.declare(definition, &format!("{name}.{def_name}"))?;
        }
    }
    renderer.finish(name)
}

/// Collects declarations for one payload root.
struct Renderer {
    prefix: String,
    declarations: BTreeMap<String, String>,
    declared: BTreeSet<String>,
}

impl Renderer {
    /// Create a renderer whose declarations are qualified by `prefix`.
    fn new(prefix: &str) -> Self {
        Self {
            prefix: prefix.to_string(),
            declarations: BTreeMap::new(),
            declared: BTreeSet::new(),
        }
    }

    /// Declare `schema` under `name`, returning the usable type expression.
    fn declare(&mut self, schema: &Value, name: &str) -> Result<String, String> {
        if self.declared.contains(name) {
            return Ok(name.to_string());
        }
        self.declared.insert(name.to_string());
        let declaration = self.declaration(schema, name)?;
        self.declarations.insert(name.to_string(), declaration);
        Ok(name.to_string())
    }

    /// Build the complete declaration text for one named schema.
    fn declaration(&mut self, schema: &Value, name: &str) -> Result<String, String> {
        match schema {
            Value::Bool(true) => Ok(format!("---@alias {name} any\n")),
            Value::Bool(false) => Err(format!("{name}: `false` schema is unsatisfiable")),
            Value::Object(map) => {
                validate_keys(map)?;
                if map.contains_key("$defs") {
                    return Err(format!("{name}: nested `$defs` is unsupported"));
                }
                if is_object_schema(map) {
                    return self.class_declaration(map, name);
                }
                if map.contains_key("allOf") {
                    let merged = all_of_schema(map)?;
                    let merged = merged
                        .as_object()
                        .ok_or_else(|| format!("{name}: merged `allOf` must be an object"))?;
                    return self.class_declaration(merged, name);
                }
                let expression = self.type_expr(schema, name)?;
                Ok(format!(
                    "{}{}",
                    doc_lines(map, combinator_note(map)),
                    alias_declaration(name, &expression),
                ))
            }
            _ => Err(format!("{name}: schema must be an object or a boolean")),
        }
    }

    /// Render one object schema as a `---@class` declaration.
    fn class_declaration(
        &mut self,
        map: &Map<String, Value>,
        name: &str,
    ) -> Result<String, String> {
        let required = required_set(map)?;
        let properties = map.get("properties").and_then(Value::as_object);
        let mut fields = String::new();
        if let Some(properties) = properties {
            let sorted: BTreeMap<&String, &Value> = properties.iter().collect();
            for (property, schema) in sorted {
                let hint = format!("{name}.{}", pascal_case(property)?);
                let expression = self.type_expr(schema, &hint)?;
                let optional = if required.contains(property.as_str()) {
                    ""
                } else {
                    "?"
                };
                fields.push_str(&format!(
                    "---@field {}{optional} {expression}{}\n",
                    field_name(property)?,
                    field_comment(
                        schema,
                        &format!("---@field {}{optional} {expression}", field_name(property)?)
                    ),
                ));
            }
        }
        match map.get("additionalProperties") {
            None | Some(Value::Bool(false)) => {}
            Some(Value::Bool(true)) => fields.push_str("---@field [string] any\n"),
            Some(schema @ Value::Object(_)) => {
                let expression = self.type_expr(schema, &format!("{name}.Additional"))?;
                fields.push_str(&format!("---@field [string] {expression}\n"));
            }
            Some(other) => {
                return Err(format!(
                    "{name}: unsupported `additionalProperties` value {other}"
                ))
            }
        }
        Ok(format!(
            "{}---@class {name}\n{fields}",
            doc_lines(map, None)
        ))
    }

    /// Render a schema as an inline LuaLS type expression.
    ///
    /// `hint` names generated declarations for nested structural nodes.
    fn type_expr(&mut self, schema: &Value, hint: &str) -> Result<String, String> {
        match schema {
            Value::Bool(true) => Ok("any".to_string()),
            Value::Bool(false) => Err(format!("{hint}: `false` schema is unsatisfiable")),
            Value::Object(map) => {
                validate_keys(map)?;
                if map.contains_key("$defs") {
                    return Err(format!("{hint}: nested `$defs` is unsupported"));
                }
                if let Some(reference) = map.get("$ref") {
                    reject_ref_siblings(map, reference)?;
                    return reference_type(reference, &self.prefix);
                }
                if map.contains_key("const") || map.contains_key("enum") {
                    if let Some(combinator) = combinator_key(map) {
                        return Err(format!(
                            "`{}` beside `{combinator}` is unsupported; sibling constraints would be dropped",
                            if map.contains_key("const") { "const" } else { "enum" }
                        ));
                    }
                    return if let Some(value) = map.get("const") {
                        literal(value)
                    } else {
                        literals(map.get("enum").expect("enum key is present"))
                    };
                }
                if let Some(combinator) = combinator_key(map) {
                    match combinator {
                        "allOf" => {
                            let merged = all_of_schema(map)?;
                            return self.declare(&merged, hint);
                        }
                        key => {
                            let siblings = structural_siblings(map, key)?;
                            let values = map[key]
                                .as_array()
                                .ok_or_else(|| format!("`{key}` must be an array"))?;
                            if values.is_empty() {
                                return Err(format!("`{key}` must not be empty"));
                            }
                            let mut members = Vec::new();
                            for (index, value) in values.iter().enumerate() {
                                let variant_name = format!("{hint}.Variant{}", index + 1);
                                let merged = match &siblings {
                                    Some(siblings) => {
                                        let variant = value.as_object().ok_or_else(|| {
                                            format!(
                                                "`{key}` sibling constraints require object variants; found {value}"
                                            )
                                        })?;
                                        if !is_object_schema(variant) {
                                            return Err(format!(
                                                "`{key}` sibling constraints require object variants; found {value}"
                                            ));
                                        }
                                        Value::Object(merge_objects(&[variant, siblings])?)
                                    }
                                    None => value.clone(),
                                };
                                let merged_map = merged
                                    .as_object()
                                    .ok_or_else(|| format!("`{key}` variants must be objects"))?;
                                if is_object_schema(merged_map) {
                                    members.push(self.declare(&merged, &variant_name)?);
                                } else {
                                    members.push(self.type_expr(&merged, &variant_name)?);
                                }
                            }
                            return Ok(members.join("|"));
                        }
                    }
                }
                match map.get("type") {
                    Some(Value::String(kind)) => self.primitive(kind, map, hint),
                    Some(Value::Array(kinds)) => {
                        let mut rendered = Vec::new();
                        for kind in kinds {
                            let kind = kind.as_str().ok_or_else(|| {
                                "`type` array entries must be strings".to_string()
                            })?;
                            rendered.push(self.primitive(kind, map, hint)?);
                        }
                        if rendered.is_empty() {
                            return Err("`type` array must not be empty".to_string());
                        }
                        Ok(rendered.join("|"))
                    }
                    Some(other) => Err(format!("unsupported `type` value {other}")),
                    None => {
                        if map.contains_key("properties")
                            || map.contains_key("additionalProperties")
                        {
                            self.declare(schema, hint)
                        } else {
                            Ok("any".to_string())
                        }
                    }
                }
            }
            _ => Err("schema must be an object or a boolean".to_string()),
        }
    }

    /// Render one primitive JSON Schema type, delegating structural shapes.
    fn primitive(
        &mut self,
        kind: &str,
        map: &Map<String, Value>,
        hint: &str,
    ) -> Result<String, String> {
        match kind {
            "object" => self.declare(&Value::Object(map.clone()), hint),
            "array" => {
                let items = map.get("items").ok_or_else(|| {
                    format!("{hint}: arrays require `items`; tuples are unsupported")
                })?;
                let item = self.type_expr(items, &format!("{hint}.Item"))?;
                Ok(array_type(&item))
            }
            "string" => Ok("string".to_string()),
            "integer" => Ok("integer".to_string()),
            "number" => Ok("number".to_string()),
            "boolean" => Ok("boolean".to_string()),
            "null" => Ok("nil".to_string()),
            other => Err(format!("unsupported JSON Schema type {other:?}")),
        }
    }

    /// Emit declarations with the root first, then the remaining names sorted.
    fn finish(self, root: &str) -> Result<String, String> {
        let root_name = format!("{root}.Root");
        let mut names: Vec<&String> = self.declarations.keys().collect();
        names.sort_by_key(|name| (*name != &root_name, name.as_str()));
        let mut out = String::new();
        for (index, name) in names.iter().enumerate() {
            if index > 0 {
                out.push('\n');
            }
            out.push_str(
                self.declarations
                    .get(*name)
                    .expect("collected declaration exists"),
            );
        }
        Ok(out)
    }
}

/// Name of the root type declared by one schema artifact.
fn root_name(schema: &Value) -> Result<String, String> {
    let title = schema
        .get("title")
        .and_then(Value::as_str)
        .ok_or_else(|| "schema root is missing `title`".to_string())?;
    validate_identifier(title)?;
    Ok(title.to_string())
}

/// Whether a schema node is a plain object shape renderable as a class.
fn is_object_schema(map: &Map<String, Value>) -> bool {
    !map.contains_key("$ref")
        && !map.contains_key("const")
        && !map.contains_key("enum")
        && combinator_key(map).is_none()
        && (map.get("type") == Some(&Value::String("object".to_string()))
            || map.contains_key("properties")
            || map.contains_key("additionalProperties"))
}

/// First combinator keyword present in a schema node.
fn combinator_key(map: &Map<String, Value>) -> Option<&'static str> {
    ["oneOf", "anyOf", "allOf"]
        .into_iter()
        .find(|key| map.contains_key(*key))
}

/// Document what a union combinator means, so `anyOf` is not read as `allOf`.
fn combinator_note(map: &Map<String, Value>) -> Option<&'static str> {
    match combinator_key(map) {
        Some("oneOf") => Some("Exactly one of the alternative shapes applies."),
        Some("anyOf") => Some("Any of the alternative shapes may apply."),
        _ => None,
    }
}

/// Read a schema's `required` list.
fn required_set(map: &Map<String, Value>) -> Result<BTreeSet<&str>, String> {
    map.get("required")
        .map(|value| {
            value
                .as_array()
                .ok_or_else(|| "`required` must be an array".to_string())?
                .iter()
                .map(|name| {
                    name.as_str()
                        .ok_or_else(|| "`required` entries must be strings".to_string())
                })
                .collect()
        })
        .transpose()
        .map(|value| value.unwrap_or_default())
}

/// Structural constraints sitting beside a combinator in the same schema node.
///
/// JSON Schema applies keywords beside `allOf`, `anyOf` and `oneOf` to the
/// same instance, so rendering only the combinator would silently drop
/// constraints such as `SerializedItem.activationSteps`. Returns `None` when
/// the node carries no sibling constraint.
fn structural_siblings(
    map: &Map<String, Value>,
    combinator: &str,
) -> Result<Option<Map<String, Value>>, String> {
    const NON_STRUCTURAL: &[&str] = &[
        "$schema",
        "$defs",
        "title",
        "description",
        "examples",
        "default",
        "deprecated",
        "readOnly",
        "writeOnly",
        "format",
        "minimum",
        "maximum",
        "exclusiveMinimum",
        "exclusiveMaximum",
        "multipleOf",
        "minLength",
        "maxLength",
        "pattern",
        "oneOf",
        "anyOf",
        "allOf",
    ];
    let mut siblings = Map::new();
    for (key, value) in map {
        if NON_STRUCTURAL.contains(&key.as_str()) {
            continue;
        }
        if key == "type" {
            if value == "object" {
                continue;
            }
            return Err(format!("unsupported `type` {value} beside `{combinator}`"));
        }
        if !matches!(
            key.as_str(),
            "properties" | "required" | "additionalProperties"
        ) {
            return Err(format!("unsupported `{key}` beside `{combinator}`"));
        }
        siblings.insert(key.clone(), value.clone());
    }
    if siblings.is_empty() {
        return Ok(None);
    }
    Ok(Some(siblings))
}

/// Reject sibling constraints the generator cannot attach to a reference.
fn reject_ref_siblings(map: &Map<String, Value>, reference: &Value) -> Result<(), String> {
    if reference.as_str().is_none() {
        return Err("`$ref` must be a string".to_string());
    }
    const ALLOWED: &[&str] = &[
        "$schema",
        "$ref",
        "title",
        "description",
        "examples",
        "default",
        "deprecated",
        "readOnly",
        "writeOnly",
    ];
    for key in map.keys() {
        if !ALLOWED.contains(&key.as_str()) {
            return Err(format!(
                "unsupported `{key}` beside `$ref`; sibling constraints would be dropped"
            ));
        }
    }
    Ok(())
}

/// Merge an `allOf` node and its structural siblings into one object schema.
fn all_of_schema(map: &Map<String, Value>) -> Result<Value, String> {
    let members = map
        .get("allOf")
        .and_then(Value::as_array)
        .ok_or_else(|| "`allOf` must be an array".to_string())?;
    if members.is_empty() {
        return Err("`allOf` must not be empty".to_string());
    }
    let mut sources = Vec::new();
    for member in members {
        let member = member
            .as_object()
            .ok_or_else(|| "`allOf` members must be objects".to_string())?;
        sources.push(member.clone());
    }
    if let Some(siblings) = structural_siblings(map, "allOf")? {
        sources.push(siblings);
    }
    let references: Vec<&Map<String, Value>> = sources.iter().collect();
    Ok(Value::Object(merge_objects(&references)?))
}

/// Merge object schemas into the intersection of their constraints.
///
/// This is the honest LuaLS representation of `allOf`: LuaLS has no
/// intersection operator, so object intersections become one class containing
/// every constrained property. Non-object intersections fail loudly.
fn merge_objects(members: &[&Map<String, Value>]) -> Result<Map<String, Value>, String> {
    const IGNORED: &[&str] = &[
        "$schema",
        "title",
        "description",
        "examples",
        "default",
        "deprecated",
        "readOnly",
        "writeOnly",
        "format",
        "minimum",
        "maximum",
        "exclusiveMinimum",
        "exclusiveMaximum",
        "multipleOf",
        "minLength",
        "maxLength",
        "pattern",
    ];
    let mut properties = Map::new();
    let mut required = BTreeSet::new();
    let mut additional: Option<Value> = None;
    let mut description: Option<String> = None;
    for member in members {
        for (key, value) in *member {
            match key.as_str() {
                "type" => {
                    if value != "object" {
                        return Err(format!("unsupported `type` {value} in an intersection"));
                    }
                }
                "properties" => {
                    let entries = value
                        .as_object()
                        .ok_or_else(|| "`properties` must be an object".to_string())?;
                    for (name, schema) in entries {
                        if let Some(existing) = properties.get(name) {
                            if existing != schema {
                                return Err(format!(
                                    "conflicting property `{name}` in an intersection"
                                ));
                            }
                        }
                        properties.insert(name.clone(), schema.clone());
                    }
                }
                "required" => {
                    let names = value
                        .as_array()
                        .ok_or_else(|| "`required` must be an array".to_string())?;
                    for name in names {
                        let name = name
                            .as_str()
                            .ok_or_else(|| "`required` entries must be strings".to_string())?;
                        required.insert(name.to_string());
                    }
                }
                "additionalProperties" => {
                    additional = merge_additional(additional, value.clone())?;
                }
                key if IGNORED.contains(&key) => {
                    if key == "description" && description.is_none() {
                        description = value.as_str().map(str::to_string);
                    }
                }
                key => return Err(format!("unsupported `{key}` in an intersection")),
            }
        }
    }
    let mut out = Map::new();
    out.insert("type".to_string(), Value::String("object".to_string()));
    if !properties.is_empty() {
        out.insert("properties".to_string(), Value::Object(properties));
    }
    if !required.is_empty() {
        out.insert(
            "required".to_string(),
            Value::Array(required.into_iter().map(Value::String).collect()),
        );
    }
    if let Some(additional) = additional {
        out.insert("additionalProperties".to_string(), additional);
    }
    if let Some(description) = description {
        out.insert("description".to_string(), Value::String(description));
    }
    Ok(out)
}

/// Combine `additionalProperties` constraints under intersection semantics.
fn merge_additional(existing: Option<Value>, incoming: Value) -> Result<Option<Value>, String> {
    match (existing, incoming) {
        (Some(Value::Bool(false)), _) | (_, Value::Bool(false)) => Ok(Some(Value::Bool(false))),
        (None, Value::Bool(true)) | (Some(Value::Bool(true)), Value::Bool(true)) => Ok(None),
        (None, schema) => Ok(Some(schema)),
        (Some(Value::Bool(true)), schema) => Ok(Some(schema)),
        (Some(existing), schema) if existing == schema => Ok(Some(existing)),
        (Some(existing), schema) => Err(format!(
            "conflicting `additionalProperties` in an intersection: {existing} and {schema}"
        )),
    }
}

/// Render one array type, grouping compound item types.
fn array_type(item: &str) -> String {
    if item.contains('|') {
        format!("table<integer, {item}>")
    } else {
        format!("{item}[]")
    }
}

/// Validate a `$ref` and render its qualified declaration name.
fn reference_type(value: &Value, prefix: &str) -> Result<String, String> {
    let reference = value
        .as_str()
        .ok_or_else(|| "`$ref` must be a string".to_string())?;
    if reference == "#" {
        return Ok(format!("{prefix}.Root"));
    }
    let name = reference
        .strip_prefix("#/$defs/")
        .ok_or_else(|| format!("unsupported `$ref` {reference:?}"))?;
    if name.contains('/') {
        return Err(format!("unsupported nested `$ref` {reference:?}"));
    }
    validate_identifier(name)?;
    Ok(format!("{prefix}.{name}"))
}

/// Render a `const` value as a LuaLS literal type.
fn literal(value: &Value) -> Result<String, String> {
    match value {
        Value::String(text) => lua_string(text),
        Value::Bool(flag) => Ok(flag.to_string()),
        Value::Number(number) => Ok(number.to_string()),
        Value::Null => Ok("nil".to_string()),
        other => Err(format!("unsupported const/enum value {other}")),
    }
}

/// Render an `enum` array as a literal union.
fn literals(value: &Value) -> Result<String, String> {
    let values = value
        .as_array()
        .ok_or_else(|| "`enum` must be an array".to_string())?;
    if values.is_empty() {
        return Err("`enum` must not be empty".to_string());
    }
    let mut rendered = Vec::new();
    for value in values {
        rendered.push(literal(value)?);
    }
    Ok(rendered.join("|"))
}

/// Quote a string for a LuaLS literal type.
fn lua_string(text: &str) -> Result<String, String> {
    let mut out = String::from("\"");
    for character in text.chars() {
        match character {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            character if (character as u32) < 0x20 => {
                return Err(format!("unsupported control character in literal {text:?}"))
            }
            character => out.push(character),
        }
    }
    out.push('"');
    Ok(out)
}

/// Render a usable LuaLS field name.
fn field_name(name: &str) -> Result<String, String> {
    validate_identifier(name)?;
    Ok(name.to_string())
}

/// Convert a camelCase property name into a declaration name segment.
fn pascal_case(name: &str) -> Result<String, String> {
    let mut characters = name.chars();
    let first = characters
        .next()
        .ok_or_else(|| "property names must not be empty".to_string())?;
    let mut out: String = first.to_uppercase().collect();
    out.extend(characters);
    validate_identifier(&out)?;
    Ok(out)
}

/// Render a field description and annotation-only constraints.
fn field_comment(schema: &Value, field_prefix: &str) -> String {
    let Some(map) = schema.as_object() else {
        return String::new();
    };
    let mut parts = Vec::new();
    if let Some(description) = map.get("description").and_then(Value::as_str) {
        parts.push(description.split_whitespace().collect::<Vec<_>>().join(" "));
    }
    let mut annotations = Vec::new();
    for key in [
        "format",
        "minimum",
        "maximum",
        "exclusiveMinimum",
        "exclusiveMaximum",
        "multipleOf",
        "minLength",
        "maxLength",
        "pattern",
    ] {
        if let Some(value) = map.get(key) {
            annotations.push(format!("{key}: {value}"));
        }
    }
    if let Some(value) = map.get("default") {
        annotations.push(format!("default: {value}"));
    }
    if map.get("deprecated") == Some(&Value::Bool(true)) {
        annotations.push("deprecated".to_string());
    }
    if !annotations.is_empty() {
        parts.push(annotations.join("; "));
    }
    wrap_inline_comment(field_prefix, &parts.join("; "))
}

/// Render description and generated semantic notes as LuaLS doc lines.
fn doc_lines(map: &Map<String, Value>, note: Option<&str>) -> String {
    let mut out = String::new();
    if let Some(description) = map.get("description").and_then(Value::as_str) {
        for line in description.lines() {
            if line.is_empty() {
                out.push_str("---\n");
            } else {
                out.push_str(&wrap_doc_line("--- ", line));
            }
        }
    }
    if let Some(note) = note {
        out.push_str(&wrap_doc_line("--- ", note));
    }
    out
}

/// Wrap generated prose comments without splitting a word or changing text.
fn wrap_doc_line(prefix: &str, text: &str) -> String {
    wrap_words(prefix, text, 120)
}

/// Keep a field's inline description within Luacheck's configured line limit.
fn wrap_inline_comment(prefix: &str, text: &str) -> String {
    if text.is_empty() {
        return String::new();
    }
    let first_prefix = format!("{prefix} # ");
    let mut lines = wrap_words(&first_prefix, text, 120);
    lines.replace_range(..prefix.len(), "");
    lines.pop();
    lines
}

fn wrap_words(prefix: &str, text: &str, limit: usize) -> String {
    let mut out = String::new();
    let mut line = prefix.to_string();
    let mut line_prefix = prefix;
    for word in text.split_whitespace() {
        if line.len() > line_prefix.len() && line.len() + 1 + word.len() > limit {
            out.push_str(&line);
            out.push('\n');
            line = "--- ".to_string();
            line_prefix = "--- ";
        }
        if line.len() > line_prefix.len() && !line.ends_with(' ') {
            line.push(' ');
        }
        line.push_str(word);
    }
    out.push_str(&line);
    out.push('\n');
    out
}

fn alias_declaration(name: &str, expression: &str) -> String {
    let (mut quoted, mut escaped, mut depth) = (false, false, 0usize);
    let mut alternatives = expression.split(|character| {
        if quoted {
            if escaped {
                escaped = false;
            } else if character == '\\' {
                escaped = true;
            } else if character == '"' {
                quoted = false;
            }
            return false;
        }
        match character {
            '"' => quoted = true,
            '(' | '[' | '{' | '<' => depth += 1,
            ')' | ']' | '}' | '>' => depth -= 1,
            '|' if depth == 0 => return true,
            _ => {}
        }
        false
    });
    let first = alternatives.next().unwrap_or_default();
    let mut out = format!("---@alias {name} {first}");
    for alternative in alternatives {
        out.push_str("\n---| ");
        out.push_str(alternative);
    }
    out.push('\n');
    out
}

/// Reject schema keywords this generator cannot represent.
fn validate_keys(map: &Map<String, Value>) -> Result<(), String> {
    const ALLOWED: &[&str] = &[
        "$schema",
        "$defs",
        "$ref",
        "title",
        "description",
        "type",
        "properties",
        "required",
        "additionalProperties",
        "items",
        "oneOf",
        "anyOf",
        "allOf",
        "const",
        "enum",
        "format",
        "minimum",
        "maximum",
        "exclusiveMinimum",
        "exclusiveMaximum",
        "multipleOf",
        "minLength",
        "maxLength",
        "pattern",
        "default",
        "examples",
        "deprecated",
        "readOnly",
        "writeOnly",
    ];
    for key in map.keys() {
        if !ALLOWED.contains(&key.as_str()) {
            return Err(format!("unsupported JSON Schema keyword `{key}`"));
        }
    }
    Ok(())
}

/// Validate that a generated name segment is a plain Lua identifier.
fn validate_identifier(name: &str) -> Result<(), String> {
    let mut characters = name.chars();
    match characters.next() {
        Some(first) if first.is_ascii_alphabetic() || first == '_' => {}
        _ => return Err(format!("{name:?} is not a valid Lua identifier")),
    }
    if characters.all(|character| character.is_ascii_alphanumeric() || character == '_') {
        Ok(())
    } else {
        Err(format!("{name:?} is not a valid Lua identifier"))
    }
}
